153	    }
154	
155	    /**
156	     * Convert a row value from the public external coordinate system to our internal private coordinate system.
157	     *
158	     * <pre>
159	     * - External coordinate system: -mActiveTranscriptRows to mScreenRows-1, with the screen being 0..mScreenRows-1.
160	     * - Internal coordinate system: the mScreenRows lines starting at mScreenFirstRow comprise the screen, while the
161	     *   mActiveTranscriptRows lines ending at mScreenFirstRow-1 form the transcript (as a circular buffer).
162	     *
163	     * External ↔ Internal:
164	     *
165	     * [ ...                            ]     [ ...                                     ]
166	     * [ -mActiveTranscriptRows         ]     [ mScreenFirstRow - mActiveTranscriptRows ]
167	     * [ ...                            ]     [ ...                                     ]
168	     * [ 0 (visible screen starts here) ]  ↔  [ mScreenFirstRow                         ]
169	     * [ ...                            ]     [ ...                                     ]
170	     * [ mScreenRows-1                  ]     [ mScreenFirstRow + mScreenRows-1         ]
171	     * </pre>
172	     *
173	     * @param externalRow a row in the external coordinate system.
174	     * @return The row corresponding to the input argument in the private coordinate system.
175	     */
176	    public int externalToInternalRow(int externalRow) {
177	        if (externalRow < -mActiveTranscriptRows || externalRow > mScreenRows)
178	            throw new IllegalArgumentException("extRow=" + externalRow + ", mScreenRows=" + mScreenRows + ", mActiveTranscriptRows=" + mActiveTranscriptRows);
179	        final int internalRow = mScreenFirstRow + externalRow;
180	        return (internalRow < 0) ? (mTotalRows + internalRow) : (internalRow % mTotalRows);
181	    }
182	
183	    public void setLineWrap(int row) {
184	        mLines[externalToInternalRow(row)].mLineWrap = true;
185	    }
186	
187	    public boolean getLineWrap(int row) {
188	        return mLines[externalToInternalRow(row)].mLineWrap;
189	    }
190	
191	    public void clearLineWrap(int row) {
192	        mLines[externalToInternalRow(row)].mLineWrap = false;
193	    }
194	
195	    /**
196	     * Resize the screen which this transcript backs. Currently, this only works if the number of columns does not
197	     * change or the rows expand (that is, it only works when shrinking the number of rows).
198	     *
199	     * @param newColumns The number of columns the screen should have.
200	     * @param newRows    The number of rows the screen should have.
201	     * @param cursor     An int[2] containing the (column, row) cursor location.
202	     */
203	    public void resize(int newColumns, int newRows, int newTotalRows, int[] cursor, long currentStyle, boolean altScreen) {
204	        // newRows > mTotalRows should not normally happen since mTotalRows is TRANSCRIPT_ROWS (10000):
205	        if (newColumns == mColumns && newRows <= mTotalRows) {
206	            // Fast resize where just the rows changed.
207	            int shiftDownOfTopRow = mScreenRows - newRows;
208	            if (shiftDownOfTopRow > 0 && shiftDownOfTopRow < mScreenRows) {
209	                // Shrinking. Check if we can skip blank rows at bottom below cursor.
210	                for (int i = mScreenRows - 1; i > 0; i--) {
211	                    if (cursor[1] >= i) break;
212	                    int r = externalToInternalRow(i);
213	                    if (mLines[r] == null || mLines[r].isBlank()) {
214	                        if (--shiftDownOfTopRow == 0) break;
215	                    }
216	                }
217	            } else if (shiftDownOfTopRow < 0) {
218	                // Negative shift down = expanding. Only move screen up if there is transcript to show:
219	                int actualShift = Math.max(shiftDownOfTopRow, -mActiveTranscriptRows);
220	                if (shiftDownOfTopRow != actualShift) {
221	                    // The new lines revealed by the resizing are not all from the transcript. Blank the below ones.
222	                    for (int i = 0; i < actualShift - shiftDownOfTopRow; i++)
223	                        allocateFullLineIfNecessary((mScreenFirstRow + mScreenRows + i) % mTotalRows).clear(currentStyle);
224	                    shiftDownOfTopRow = actualShift;
225	                }
226	            }
227	            mScreenFirstRow += shiftDownOfTopRow;
228	            mScreenFirstRow = (mScreenFirstRow < 0) ? (mScreenFirstRow + mTotalRows) : (mScreenFirstRow % mTotalRows);
229	            mTotalRows = newTotalRows;
230	            mActiveTranscriptRows = altScreen ? 0 : Math.max(0, mActiveTranscriptRows + shiftDownOfTopRow);
231	            cursor[1] -= shiftDownOfTopRow;
232	            mScreenRows = newRows;
233	        } else {
234	            // Copy away old state and update new:
235	            TerminalRow[] oldLines = mLines;
236	            mLines = new TerminalRow[newTotalRows];
237	            for (int i = 0; i < newTotalRows; i++)
238	                mLines[i] = new TerminalRow(newColumns, currentStyle);
239	
240	            final int oldActiveTranscriptRows = mActiveTranscriptRows;
241	            final int oldScreenFirstRow = mScreenFirstRow;
242	            final int oldScreenRows = mScreenRows;
243	            final int oldTotalRows = mTotalRows;
244	            mTotalRows = newTotalRows;
245	            mScreenRows = newRows;
246	            mActiveTranscriptRows = mScreenFirstRow = 0;
247	            mColumns = newColumns;
248	
249	            int newCursorRow = -1;
250	            int newCursorColumn = -1;
251	            int oldCursorRow = cursor[1];
252	            int oldCursorColumn = cursor[0];
253	            boolean newCursorPlaced = false;
254	
255	            int currentOutputExternalRow = 0;
256	            int currentOutputExternalColumn = 0;
257	
258	            // Loop over every character in the initial state.
259	            // Blank lines should be skipped only if at end of transcript (just as is done in the "fast" resize), so we
260	            // keep track how many blank lines we have skipped if we later on find a non-blank line.
